[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$ProjectPath,
    [Parameter(Mandatory=$true)][string]$VerificationRoot,
    [Parameter(Mandatory=$true)][string]$PilotPlanPath,
    [Parameter(Mandatory=$true)][string]$ProvenancePath,
    [Parameter(Mandatory=$true)][string]$TelemetryResultPath,
    [switch]$BindingSmokeOnly
)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
if([string]::IsNullOrWhiteSpace($ProjectPath)-or-not[IO.Path]::IsPathRooted($ProjectPath)){throw 'PR1B v2 validation-only audit requires an explicit absolute ProjectPath.'};$ProjectPath=[IO.Path]::GetFullPath($ProjectPath)
if($BindingSmokeOnly){Write-Output("BINDING-SMOKE-PASSED|Run-Gate13RPR1BValidationOnlyPrePilotAuditV2|$ProjectPath");exit 0}
$VerificationRoot=[IO.Path]::GetFullPath($VerificationRoot);$PilotPlanPath=[IO.Path]::GetFullPath($PilotPlanPath);$ProvenancePath=[IO.Path]::GetFullPath($ProvenancePath);$TelemetryResultPath=[IO.Path]::GetFullPath($TelemetryResultPath)
Import-Module (Join-Path $ProjectPath 'Research\Gate13RPR1BOrderEffectPreparationV2.psm1') -Force
$plan=Read-Gate13RPR1BV2Json $PilotPlanPath;$provenance=Read-Gate13RPR1BV2Json $ProvenancePath;$errors=New-Object Collections.Generic.List[string];$checks=New-Object Collections.Generic.List[object]
function Add-Check([string]$Id,[bool]$Passed,[string]$Detail){$script:checks.Add([pscustomobject][ordered]@{id=$Id;passed=$Passed;detail=$Detail});if(-not$Passed){$script:errors.Add("$Id`: $Detail")}}
$summaries=[ordered]@{
 static=Join-Path $VerificationRoot 'StaticUnit\summary.json';compile=Join-Path $VerificationRoot 'Compile\summary.json';memoryPolicy=$VerificationRoot+'\MemoryPolicySelfTest.summary.json';telemetry=Join-Path $VerificationRoot 'TelemetryProbe\v2.summary.json';positiveNegative=Join-Path $VerificationRoot 'BlockVerification\summary.json';additional=Join-Path $VerificationRoot 'BlockVerificationAdditional\summary.json'
}
foreach($key in $summaries.Keys){$path=$summaries[$key];$present=Test-Path -LiteralPath $path -PathType Leaf;$passed=$present-and((Read-Gate13RPR1BV2Json $path).passed-eq$true);Add-Check ("upstream-$key") $passed $path}
$telemetry=if(Test-Path $TelemetryResultPath){Read-Gate13RPR1BV2Json $TelemetryResultPath}else{$null};Add-Check 'telemetry-v2-positive-crosscheck' ($null-ne$telemetry-and[string]$telemetry.resultKind-eq'gate13r-pr1b-v2-native-telemetry-probe-result-v1'-and$telemetry.passed-eq$true-and[long]$telemetry.nativeBefore.workingSetBytes-gt0-and[long]$telemetry.nativeBefore.privateMemoryBytes-gt0-and[long]$telemetry.externalQuery.workingSetBytes-gt0-and[long]$telemetry.externalQuery.privateMemoryBytes-gt0) $TelemetryResultPath
foreach($binding in @($provenance.boundFiles)){$path=Join-Path $ProjectPath ([string]$binding.relativePath).Replace('/','\');Add-Check ('hash-'+([string]$binding.relativePath).Replace('/','_').Replace('.','_')) ((Test-Path $path)-and(Get-Gate13RPR1BV2LowerSha256 $path)-eq[string]$binding.sha256) ([string]$binding.relativePath)}
$prewritePath=Join-Path $ProjectPath 'Research\Gate13R_PR1B_v2_PreWrite_Preservation_Audit.v1.json';$prewrite=Read-Gate13RPR1BV2Json $prewritePath
foreach($frozen in @($prewrite.frozenReferences)){$path=Join-Path $ProjectPath ([string]$frozen.relativePath).Replace('/','\');Add-Check ('frozen-'+([string]$frozen.relativePath).Replace('/','_').Replace('.','_')) ((Test-Path $path)-and(Get-Gate13RPR1BV2LowerSha256 $path)-eq[string]$frozen.sha256) ([string]$frozen.relativePath)}
$attempt1Root=Join-Path $ProjectPath ([string]$prewrite.attempt1.rootRelativePath).Replace('/','\');$attempt1Files=@(Get-ChildItem -LiteralPath $attempt1Root -Recurse -File -Force);$attempt1Bytes=[long](($attempt1Files|Measure-Object Length -Sum).Sum);Add-Check 'attempt1-root-inventory-unchanged' ($attempt1Files.Count-eq[int]$prewrite.attempt1.fileCount-and$attempt1Bytes-eq[long]$prewrite.attempt1.rawBytes) "files=$($attempt1Files.Count) bytes=$attempt1Bytes"
try{Assert-Gate13RPR1BV2PlanIdentity $plan;$campaigns=@(Get-Gate13RPR1BV2Campaigns -ProjectPath $ProjectPath -Plan $plan);$measured=@(Get-Gate13RPR1BV2ProcessSchedule -Plan $plan -Campaigns $campaigns -AnalysisRole measured-non-formal-pilot);$warmup=@(Get-Gate13RPR1BV2ProcessSchedule -Plan $plan -Campaigns $campaigns -AnalysisRole excluded-warmup);$schedule=Test-Gate13RPR1BV2Schedule -Plan $plan -Measured $measured -Warmup $warmup;Add-Check 'schedule-deterministic-regeneration' ($schedule.passed-eq$true) (($schedule.errors)-join'; ')}catch{Add-Check 'schedule-deterministic-regeneration' $false $_.Exception.Message}
$positiveRoot=Join-Path $VerificationRoot 'BlockVerification\positive-mirrored';$evaluations=@(Get-ChildItem -LiteralPath $positiveRoot -Recurse -Filter 'memory-gate-evaluation.json' -File -ErrorAction SilentlyContinue);Add-Check 'positive-memory-evaluation-count' ($evaluations.Count-eq8) "count=$($evaluations.Count)"
$negativeRoot=Join-Path $VerificationRoot 'BlockVerification\negative-fail-closed\per-agent';$negativeFailure=if(Test-Path (Join-Path $negativeRoot 'block-failure.json')){Read-Gate13RPR1BV2Json (Join-Path $negativeRoot 'block-failure.json')}else{$null};$negativeCheckpoint=if(Test-Path (Join-Path $negativeRoot 'block-checkpoint.json')){Read-Gate13RPR1BV2Json (Join-Path $negativeRoot 'block-checkpoint.json')}else{$null};Add-Check 'negative-fail-closed-terminal' ($null-ne$negativeFailure-and$null-ne$negativeCheckpoint-and[int]$negativeFailure.completedSampleCount-eq1-and[string]$negativeCheckpoint.status-eq'failed-no-auto-retry') $negativeRoot
$pilotRoot=Join-Path $ProjectPath ([string]$plan.paths.pilotRootRelativePath).Replace('/','\');$formalRoot=Join-Path $ProjectPath ([string]$plan.paths.reservedFormalRootRelativePath).Replace('/','\')
Add-Check 'pilot-root-absent' (-not(Test-Path $pilotRoot)) $pilotRoot;Add-Check 'formal-root-absent' (-not(Test-Path $formalRoot)) $formalRoot;Add-Check 'unity-closed' (@(Get-Process -Name Unity -ErrorAction SilentlyContinue).Count-eq0) 'No Unity process may remain.';Add-Check 'unity-lock-absent' (-not(Test-Path (Join-Path $ProjectPath 'Temp\UnityLockfile'))) 'Unity project lock must be absent.'
$summary=[ordered]@{schemaVersion=2;summaryKind='gate13r-pr1b-v2-validation-only-pre-pilot-audit-v1';savedAtUtc=[DateTime]::UtcNow.ToString('o');pilotPlanSha256=Get-Gate13RPR1BV2LowerSha256 $PilotPlanPath;provenanceSha256=Get-Gate13RPR1BV2LowerSha256 $ProvenancePath;telemetryResultSha256=Get-Gate13RPR1BV2LowerSha256 $TelemetryResultPath;checkCount=$checks.Count;passedCheckCount=@($checks|Where-Object passed).Count;checks=$checks.ToArray();errors=$errors.ToArray();pilotExecutionAuthorized=$errors.Count-eq0;formalCampaign=$false;gate13rFormalAuthorized=$false;gate14rAuthorized=$false;passed=$errors.Count-eq0}
Write-Gate13RPR1BV2AtomicUtf8NoBomJson -Path (Join-Path $VerificationRoot 'ValidationOnlyPrePilotAudit.summary.json') -Value $summary -Depth 50
if($errors.Count){Write-Error("PR1B v2 validation-only pre-pilot audit failed: "+($errors-join'; '));exit 1};Write-Host 'PR1B v2 validation-only pre-pilot audit passed.' -ForegroundColor Green;exit 0
